선택적 매개변수 하나에 여러 의미가 섞여 있다.
업데이트 요청에서는 특히 다음 세 상태를 구분해야 할 수 있다.
undefined → 변경하지 않음
null → 기존 만료일 제거
Date → 새로운 만료일 설정
이 계약을 타입으로 표현할 수 있다.
interface UpdateCouponInput {
expiresAt?:
| Date
| null;
}
function updateCoupon(
coupon: Coupon,
input: UpdateCouponInput
): Coupon {
if (
input.expiresAt === undefined
) {
return coupon;
}
return {
...coupon,
expiresAt: input.expiresAt,
};
}
호출 방법에 따라 의도가 달라진다.
updateCoupon(coupon, {});
// 만료일을 변경하지 않는다.
updateCoupon(coupon, {
expiresAt: null,
});
// 기존 만료일을 제거한다.
updateCoupon(coupon, {
expiresAt:
new Date("2026-12-31"),
});
// 새로운 만료일을 설정한다.
