interface RedemptionContext {
userId: string;
approvedByIssuer: boolean;
now: Date;
}
function canRedeemCoupon(
coupon: Coupon,
context: RedemptionContext
): boolean {
const isRecipient =
coupon.recipientId ===
context.userId;
const hasRemainingUses =
coupon.remainingUses > 0;
const isWithinExpiry =
coupon.expiresAt === null ||
coupon.expiresAt >
context.now;
const isAllowedStatus =
coupon.status === "active" ||
(
coupon.status === "paused" &&
context.approvedByIssuer
);
return (
isRecipient &&
hasRemainingUses &&
isWithinExpiry &&
isAllowedStatus
);
}
