async function handleRedeemCoupon(
request: Request
): Promise<CouponResponse> {
const couponId =
parseCouponId(
request.params.couponId
);
const userId =
request.currentUser.id;
const coupon =
await couponRepository.findById(
couponId
);
if (!coupon) {
throw new Error(
"쿠폰을 찾을 수 없다."
);
}
const now = new Date();
const redeemedCoupon =
applyCouponRedemption(
coupon,
{
userId,
now,
}
);
const savedCoupon =
await couponRepository.save(
redeemedCoupon
);
return toCouponResponse(
savedCoupon
);
}
